+/* Remove all references to a session header without trusting its intrusive
+ * list links. This also repairs a list where the same header was inserted
+ * twice and became self-linked. */
+static void
+scrubSessionFromManagedChannels(UA_Server *server, UA_Session *session) {
+    UA_SessionHeader *target = &session->header;
+    channel_list_entry *centry;
+
+    LIST_FOREACH(centry, &server->secureChannelManager.channels, pointers) {
+        UA_SecureChannel *channel = &centry->channel;
+        UA_SessionHeader *current = LIST_FIRST(&channel->sessions);
+        UA_SessionHeader **tail = &channel->sessions.lh_first;
+        UA_Boolean targetSeen = false;
+
+        LIST_INIT(&channel->sessions);
+        while(current) {
+            /* A second occurrence of the target is a target-containing cycle. */
+            if(current == target && targetSeen)
+                break;
+
+            /* Stop on any other cycle already copied to the rebuilt list. */
+            UA_SessionHeader *seen;
+            for(seen = LIST_FIRST(&channel->sessions); seen;
+                seen = LIST_NEXT(seen, pointers)) {
+                if(seen == current)
+                    break;
+            }
+            if(seen)
+                break;
+
+            UA_SessionHeader *next = LIST_NEXT(current, pointers);
+            if(current == target) {
+                targetSeen = true;
+            } else {
+                *tail = current;
+                current->pointers.le_prev = tail;
+                tail = &current->pointers.le_next;
+            }
+            current = next;
+        }
+        *tail = NULL;
+    }
+
+    target->channel = NULL;
+    target->pointers.le_next = NULL;
+    target->pointers.le_prev = NULL;
+}
